CREATE FUNCTION public.pending_leave_review_ids() RETURNS SETOF uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT id FROM public.leave_requests WHERE status='pending' AND public.is_company_manager() AND public.workspace_thread_can('leave',id) $$;
REVOKE ALL ON FUNCTION public.pending_leave_review_ids() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.pending_leave_review_ids() TO authenticated,service_role;
DO $$ DECLARE f text; BEGIN f=pg_get_functiondef('public.guard_claim_incentive()'::regprocedure); f=replace(f,'(NEW.open_to_claim OR claim_incentive_all_jobs)','(claim_incentive_all_jobs OR (NEW.scheduled_date IS NOT NULL AND NOT NEW.claim_hold AND (NEW.open_to_claim OR (NEW.assigned_technician_id IS NULL AND public.company_module_access(NEW.company_id,''skills_dispatch'')))))'); EXECUTE f; END $$;
CREATE FUNCTION public.leave_thread_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.workspace_thread_messages WHERE kind='leave' AND record_id=OLD.id) THEN RAISE EXCEPTION 'Leave with conversation history must be retained'; END IF; RETURN OLD; END $$;
CREATE TRIGGER retain_leave_conversation BEFORE DELETE ON public.leave_requests FOR EACH ROW EXECUTE FUNCTION public.leave_thread_guard();